#!/usr/bin/env python3
##--------------------------------------------------------------------------------#
# Script to plot total forces on WEC from Output.txt file generated by extractLog.sh
# Usage: python plotForces.py OF_case_directory (single or multiple cases)
##--------------------------------------------------------------------------------#
import sys
import os
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
#---------------------------------Plot settings-----------------------------#
#plt.rcParams['figure.dpi'] = 400
colors = np.array(
['#4477AA', # blue
  '#66CCEE', # cyan
  '#228833', # green
  '#CCBB44', # yellow
  '#EE6677', # red
  '#AA3377', # purple
  '#BBBBBB'] # grey]
)

# colormap from: https://personal.sron.nl/~pault/
plt.rcParams['axes.prop_cycle'] = plt.cycler(color=colors)

##--------------------------------------------------------------------------------#
# Read input data file
def readData(filePath):
    filename = os.path.join(filePath,'QP.dat')
    if (not os.path.isfile(filename)):
      print('No QP.dat file found. Run exportQP.sh first!')
      sys.exit(1)

    ufData = pd.read_csv(filename, sep="\s+|\t,", header=None, skiprows=5,
                                    names = range(100), engine="python")

    time = ufData[0]
    p0 = ufData[1]
    p1 = ufData[2]
    Q = ufData[3]

    filename = os.path.join(filePath,'porousSettings.dat')
    ufData = pd.read_csv(filename, sep="\s+|\t,", header=None,
                                    names = range(2), engine="python")

    Dcoeff = ufData[1][0]
    Icoeff = ufData[1][1]
    Lcoeff = ufData[1][2]
    Area = ufData[1][3]
    mu = 1.48e-5

    uf_slope = Area/(Dcoeff*mu*Lcoeff)

    return time, p0, p1, Q, uf_slope

##--------------------------------------------------------------------------------#
# Read inputs
nCases = len(sys.argv)-1
if (nCases < 1):
    print('\nMissing case input(s) for plotting!')
    print('\nUsage: \n \t python plotQP.py OF_case_directories\n')
    sys.exit(1)

# Plotting outputs
fig, axs = plt.subplots(2,1,figsize=(8,8), tight_layout=True)
for case in sys.argv[1:]:
    time, p0, p1, Q, uf_slope = readData(os.path.join(case,"postProcessing"))

    dp = p0-p1
    slope, intercept = np.polyfit(dp, Q, deg=1)
    pFit = np.linspace(np.min(dp), np.max(dp), 100)
    QFit = slope*pFit + intercept

    axs[0].plot(dp, Q, '.', label=case+r' $(A/{D \mu L}: $' + str(round(uf_slope,6))+')')
    axs[0].plot(pFit, QFit, label='m: '+str(round(slope,6))+'. b: '+str(round(intercept,5)))
    axs[1].plot(time, dp, label=case)

yLabels = ['Q (m3/s)','P0-P1 (Pa)']
xLabels = ['P0-P1 (Pa)','Time (s)']
for i in range(2):
    axs[i].legend()
    axs[i].set_ylabel(yLabels[i])
    axs[i].set_xlabel(xLabels[i])

plt.legend()
plt.show()
